args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?spouse ?spouseLabel ?father ?fatherLabel WHERE {
  dbr:Halime_Hatun dbp:spouse ?spouse .
  OPTIONAL { ?spouse (dbp:father|dbo:parent|dbo:father) ?father. }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel FILTER(lang(?spouseLabel) = 'en') }
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel) = 'en') }
}

